#include <iostream>

// Inline function with a default argument
inline int computeScale(int val, int factor = 3) {
    return val * factor;
}

// Demonstrates pass-by-value and pass-by-reference
void demoParams(int byVal, int& byRef) {
    byVal += 100;
    byRef += 100;
}

// Demonstrates static local variable retention
int getInvocationCounter() {
    static int callCount = 0;
    callCount++;
    return callCount;
}

int main() {
    int x = 10, y = 20;
    demoParams(x, y);
    std::cout << "x (by-value): " << x << " | y (by-ref): " << y << "\n";

    std::cout << "Scale default: " << computeScale(5) << "\n";
    std::cout << "Scale custom: " << computeScale(5, 4) << "\n";

    std::cout << "Call 1: " << getInvocationCounter() << "\n";
    std::cout << "Call 2: " << getInvocationCounter() << "\n";
    std::cout << "Call 3: " << getInvocationCounter() << "\n";

    return 0;
}

#include <iostream>

// Bottom-up component 1: Solves triangular formula m*(m+1)/2 (Exercise 6.1)
int getTriangularNumber(int n) {
    return n * (n + 1) / 2;
}

// Bottom-up component 2: Sum cubes of digits (Exercise 6.3)
int cubeOfDigits(int number) {
    int sum = 0;
    int temp = (number < 0) ? -number : number;
    while (temp > 0) {
        int digit = temp % 10;
        sum += (digit * digit * digit);
        temp /= 10;
    }
    return sum;
}

// Higher-level abstraction leveraging cubeOfDigits
bool isArmstrong(int number) {
    return cubeOfDigits(number) == number;
}

int main() {
    std::cout << "Triangular numbers [1..5]: ";
    for (int i = 1; i <= 5; ++i) {
        std::cout << getTriangularNumber(i) << (i == 5 ? "" : ", ");
    }
    std::cout << "\n";

    int testVal = 153;
    std::cout << testVal << (isArmstrong(testVal) ? " is Armstrong" : " is not Armstrong") << "\n";

    return 0;
}
